type Dict = Record<string, string>;
type Bag = Record<string, unknown>;

/* ---------- shell glue ---------- */
/** LANGS (L7470) and I18N (L7480): plain objects keyed by language code in the source. */
const LANGS = LANGS0 as Record<string, { name: string; locale: string; [k: string]: unknown }>;
const I18N = I18N0 as Record<string, Dict>;
/* Product phase strings (dcx_*), merged once into the OS dictionaries. */
for (const l of Object.keys(PX_I18N) as (keyof typeof PX_I18N)[]) Object.assign((I18N[l] ||= {}), PX_I18N[l]);
/** lang (the OS language global). */
const lang = (): Lang => { const h = document.documentElement.lang; return isLang(h) ? h : "en"; };
/** t (L7507): the shell's dictionary with {x} substitution. */
const t = (k: string, vars: Record<string, string | number> = {}) => translate(lang(), k, vars);
/** nf, loc (L7508–L7509). */
const loc = () => LANGS0[lang()].locale;
const nf = (n: number) => formatNumber(lang(), n);
/** DKE (L11239). */
const DKE = (s: unknown) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" } as Dict)[c]);
const toast = (m: string) => useShell.getState().showToast(m);
/** osMenu (L11650). The source builds the menu synchronously and the table-cell override (L18524) reads it straight back, so
 * the React menu is opened inside flushSync. */
const osMenu = (x: number, y: number, items: (MenuItem | string | null)[]) => flushSync(() => osMenuCore(x, y, items as MenuItem[]));
/** pdf.js and mammoth are self-hosted under /public/vendor, loaded on demand (feLoadScript) and read as page globals, as in the source. */
declare const pdfjsLib: DcPdfJs;
declare const mammoth: { convertToHtml: (o: { arrayBuffer: ArrayBuffer }, opt?: Bag) => Promise<{ value: string; messages: unknown[] }>; extractRawText: (o: { arrayBuffer: ArrayBuffer }) => Promise<{ value: string }> };
/** OSW.documents (the open window, L11806): its element and whether it is minimised. */
const dcWinEl = () => document.querySelector<HTMLElement>('.os-win[data-osw="documents"]');
const OSW = { get documents() { const el = dcWinEl(); return el ? { el, min: !!useWm.getState().wins.documents?.min } : undefined; } };
const tgt = (e: Event) => e.target as HTMLInputElement;
/**
 * The source's module-level document and window listeners (68 + 4). They are registered the first time the Documents
 * window mounts (dcInstallGlobal), in source order; each handler only acts while the Documents window is open.
 */
const pendingGlobal: (() => void)[] = [];
const onDoc = <K extends keyof DocumentEventMap>(ev: K, fn: (e: DocumentEventMap[K]) => void, cap?: boolean | AddEventListenerOptions) => { pendingGlobal.push(() => document.addEventListener(ev, fn, cap)); };
const onWin = <K extends keyof WindowEventMap>(ev: K, fn: (e: WindowEventMap[K]) => void, cap?: boolean) => { pendingGlobal.push(() => window.addEventListener(ev, fn, cap)); };
let globalDone = false;
export function dcInstallGlobal() { if (globalDone) return; globalDone = true; pendingGlobal.forEach((f) => f()); }


