type DcWPp = { jc?: string; pStyle?: string; pb?: boolean; numId?: string | null; ilvl?: number; outline?: number; shd?: string; bdr?: boolean; ind?: number; bidi?: boolean; line?: number; [k: string]: unknown };
type DcWSt = { type: string | null; name: string; based: string | null; r: DcWRp; p: DcWPp; def: boolean };
type DcWLvl = { fmt: string; txt?: string; start?: number };
type DcWLi = { lvl: number; h: string; fmt: string; start?: number; numId?: string | null };
type DcWCtx = { top?: boolean; link?: boolean; sdt?: { kind: string; label: string; opts: (string | null)[]; checked: boolean }; boxes?: Element[]; imgs?: { src: string; pct: number }[] };
type DcWCs = { bg?: unknown; b?: number; c?: string; al?: string };
type DcWMg = { r: number; c: number; rs: number; cs: number };
type DcWItem = { k: string; html?: string; text?: string; lv?: number; color?: string; [k: string]: unknown };
/** ODT reader styles. */
type DcORp = { b?: boolean; i?: boolean; u?: boolean; s?: boolean; color?: string | null; size?: string | null; font?: string | null; bg?: string | null; va?: string | null; [k: string]: unknown };
type DcOPp = { al?: string | null; bg?: string | null; pb?: boolean | null; bd?: boolean | null; [k: string]: unknown };
type DcOSt = { parent: string | null; display: string; outline: number; r: DcORp; p: DcOPp; master?: string | null };

/* agent 04 (stage6 L3660–L4263): RTF reader, PPTX/XLSX/CSV/PDF readers, import dialog, charts, signing */
type DcRtfSt = { b: number; i: number; u: number; s: number; cf: number; cb: number; fs: number; f: number | null; al: string; uc: number; sup: number; sub: number; skip?: number };
type DcRtfRun = { key?: string; st?: string; b?: number; i?: number; u?: number; s?: number; sup?: number; sub?: number; tx: string };
type DcRtfPict = { depth: number; hex: string; type: string; w: number; h: number; gw: number | null };
type DcRtfTbl = { k: "tbl"; rows: DcRtfRun[][][][] };
type DcRtfOut = { k: "p"; runs: DcRtfRun[]; al: string } | { k: "img"; pict: DcRtfPict } | { k: "pb" } | DcRtfTbl;
/** a cell style read from an imported file (XLSX / DOCX): background, colour, bold, alignment */
type DcImpCs = { b?: number | boolean; c?: string; bg?: string; al?: string; [k: string]: unknown };
type DcImpMg = { r: number; c: number; rs: number; cs: number };
/** one item produced by a file reader, turned into blocks by dcItemsToPages */
type DcImpItem = { k: string; lv?: number; text?: string | null; html?: string; hs?: string; bg?: string; var?: string; src?: string; cap?: string; pct?: number; exact?: boolean; rows?: string[][]; cs?: Record<string, DcImpCs>; mg?: DcImpMg[]; head?: boolean | null; w?: unknown[] | null; title?: string; ftype?: string; label?: string; opts?: string[]; checked?: boolean; [k: string]: unknown };
type DcImpSet = { fs?: number; mgx?: number; mgy?: number; font?: string; or?: string; [k: string]: string | number | boolean | null | undefined };
/** what a reader returns */
type DcImpRes = { items?: DcImpItem[]; title?: string | null; set?: DcImpSet; lang?: string | null; notes?: string[]; exact?: boolean; old?: Parameters<typeof dcFromOld>[0] };
/** one file of the import dialog */
type DcImpEn = { file: File; kind: string | null; ext: string; status?: string; err?: string | null; doc?: DcDoc; notes?: string[]; stats?: Record<string, number> };
type DcImpOpts = { dest: string; pos: string; clean: boolean; fields: boolean; pdf: string; merge: string; [k: string]: unknown };
/** DC.imp as the import dialog uses it */
type DcImpX = { files: DcImpEn[]; sel: number; opts: DcImpOpts; canAdd?: boolean };
type DcPdfRun = { t: string; b: boolean; i: boolean; h: number };
type DcPdfLine = { y: number; x: number; runs: DcPdfRun[]; h: number; maxX: number };
type DcPdfPg = { lines: DcPdfLine[]; w: number };
/** a chart series as read from a block (values may still be strings) and as drawn */
type DcCSerIn = { name?: string; vals?: (number | string | null)[]; col?: string | null };
type DcCSer = { name: string; vals: (number | null)[]; col: string };
type DcCBand = { min: number; max: number; b: [number, number, string, string][] };
type DcCTpl = { k: string; n: string; unit?: string; bands?: string; yMin?: number; yMax?: number; ref?: number; refL?: string; vlab?: boolean; trend?: boolean; lab: Record<string, string[]>; ser: [string, number[]][] };
/** multi-person signing (d.sig) */
type DcSigner = { id: string; role: string; name: string; st: string; at?: number; img?: string; how?: string; idv?: boolean; reason?: string };
type DcSigAudit = { at: number; ev: string; name?: string; role?: string; reason?: string; [k: string]: unknown };
type DcSig = { mode: string; list: DcSigner[]; audit: DcSigAudit[]; lock: boolean; hash: string; cert: boolean; doneAt?: number; lockAt?: number };
type DcCkItem = { sev: string; rule: string; msg: string; key: string; b?: string; pi?: number; ign?: boolean; [k: string]: unknown };
type DcDrawerEl = HTMLInputElement & { _w?: unknown; _wsg?: number };

/* ---- agent 05-e: signature certificate, context menus, charts, themes, tables, columns, exact PDF forms, Word-exact renderer ---- */
/** d.sig (the signature workflow state) as read by the certificate page. */
type DcESigner = { id: string; role: string; name?: string; st: string; at?: number; how?: string; idv?: unknown; reason?: string; img?: string; [k: string]: unknown };
type DcESig = { mode: string; list: DcESigner[]; audit: { at: number; ev: string; name?: string; role?: string; reason?: string; [k: string]: unknown }[]; lock: boolean; hash: string; cert: boolean; [k: string]: unknown };
/** an insertion point (page index, block index). */
type DcEAt = { pi: number; bi: number };
/** chart height drag state. */
type DcEChrs = { id: string; b: DcBlock; y0: number; h0: number; k: number; cur: number; hd: Element; be: HTMLElement };
/** document themes (built-in and "my themes"). */
type DcETheme = { id: string; acc: string; hcol: string; font: string; hfont: string; pal: string; sec: string; tbl: string; rad: number; fs?: number; [k: string]: unknown };
type DcEMyTheme = DcETheme & { name: string; logo: string };
/** table merges (b.mg) and per-cell styles (b.cs). */
type DcEMg = { r: number; c: number; rs: number; cs: number };
type DcERect = { b: DcBlock; r0: number; r1: number; c0: number; c1: number; n: number };
/** column-resize drag state. */
type DcECrs = { b: DcBlock; j: number; x0: number; W: number; ws: number[]; cols: HTMLElement[]; rtl: boolean; cur?: number[] };
/** column groups: d.set.cols[gid]. */
type DcECg = { w: number[]; line: boolean };
type DcECsz = { g: string; i: number; fr: number[]; x0: number; W: number; grid: HTMLElement; h: HTMLElement; rtl: boolean; cur?: number[] };
/** block-flow item builders passed to dcFlowX. */
type DcEFlowP = (html: string, st?: string) => void;
/** a chart block in the bundled remotion-documents model (dcChartFromRD). */
type DcERdChart = { kind?: string; horizontal?: boolean; stack?: string; donut?: boolean; series?: { name?: string; values?: (number | string | null)[]; color?: string; mark?: string }[]; refs?: { value?: number | string | null; label?: string }[]; labels?: unknown[]; title?: string; unit?: string; min?: number | null; max?: number | null; grid?: boolean; values?: boolean; legend?: boolean; legendPos?: string; yLabel?: string; note?: string; dataTable?: boolean; sort?: string; hFixed?: boolean; height?: number | string; [k: string]: unknown };
/** exact forms (d.ex): the original PDF and the fields placed on it. */
type DcEExVal = string | boolean | string[];
type DcEExWidget = { value: string; x: number; y: number; w: number; h: number; _x0?: number; _y0?: number };
type DcEExNew = { ftype: string; label: string; x: number; y: number; w: number; h: number; widgets?: DcEExWidget[]; groups?: { n: number; x: number; y: number; w: number; h: number }[]; comb?: number; line?: boolean; format?: string; unit?: string; role?: string };
type DcEExField = DcEExNew & { id: string; name?: string; page: number; section?: string; ctx?: string; src?: string; value?: DcEExVal; img?: string; signedAt?: number; hdr?: boolean };
type DcEExGuess = { ftype?: string; format?: string; unit?: string; role?: string };
type DcEExOfficial = { authority: string; file: string; ver: string; fills: string };
type DcEEx = { off?: string | null; sha?: string; b64?: string; name?: string; pages: { w: number; h: number }[]; fields: DcEExField[]; official?: DcEExOfficial | null };
type DcEExDoc = DcDoc & { ex: DcEEx };
type DcEExOpt = { title?: string; off?: string; name?: string; official?: DcEExOfficial };
type DcEExBg = { ok?: boolean; imgs?: string[]; p?: Promise<DcEExBg> };
type DcEExDrag =
  | { m: "rz"; f: DcEExField; p0: number[]; w0: number; h0: number; pt: (ev: PointerEvent) => number[]; pushed?: boolean }
  | { m: "mv"; f: DcEExField; p0: number[]; x0: number; y0: number; pt: (ev: PointerEvent) => number[]; el: HTMLElement; moved: boolean }
  | { m: "new"; pi: number; p0: number[]; pt: (ev: PointerEvent) => number[]; pg: HTMLElement; k: number; sc: number; r?: number[] };
/** pdf-lib (self-hosted under /public/vendor, read as window.PDFLib): the part used to write the answers on the original PDF. */
type DcEPdfLibPage = { getHeight: () => number; drawLine: (o: Bag) => void; drawImage: (im: unknown, o: Bag) => void; drawText: (s: string, o: Bag) => void };
type DcEPdfLibDoc = { getForm: () => { flatten: () => void }; embedFont: (f: string) => Promise<{ widthOfTextAtSize: (s: string, size: number) => number }>; embedPng: (b: Uint8Array) => Promise<{ width: number; height: number }>; getPages: () => DcEPdfLibPage[]; save: () => Promise<Uint8Array<ArrayBuffer>> };
type DcEPdfLib = { PDFDocument: { load: (b: Uint8Array | null, o?: Bag) => Promise<DcEPdfLibDoc>; create: () => Promise<DcEPdfLibDoc & { copyPages: (src: DcEPdfLibDoc, idx: number[]) => Promise<unknown[]>; addPage: (p: unknown) => void }> }; StandardFonts: Record<string, string>; rgb: (r: number, g: number, b: number) => unknown };
type DcEPdfDestroy = { destroy: () => Promise<void> };
/** Word-exact renderer (wxConvert): run / paragraph / table properties read from the DOCX XML. */
type WxBorder = { w: number; st: string; c: string; sp: number };
type WxBset = Record<string, WxBorder | null | undefined>;
type WxRunP = { b?: boolean; i?: boolean; strike?: boolean; dstrike?: boolean; caps?: boolean; smallCaps?: boolean; vanish?: boolean; u?: string; color?: string; sz?: number; font?: string | null; hl?: string | null; shd?: string | null; va?: string | null; ls?: number; rStyle?: string | null; sc?: number; pos?: number; bdr?: WxBorder | null; [k: string]: unknown };
type WxSp = { before?: number; after?: number; line?: number; rule?: string; bAuto?: number; aAuto?: number; [k: string]: number | string | undefined };
type WxInd = { left?: number; right?: number; first?: number; hang?: number };
type WxTab = { v: string | null; pos: number; lead: string };
type WxParaP = { sp?: WxSp; ind?: WxInd; jc?: string | null; pStyle?: string | null; bdr?: WxBset; shd?: string | null; tabs?: WxTab[]; num?: { id: string | null; lvl: number }; frame?: boolean; mark?: WxRunP; keepNext?: boolean; keepLines?: boolean; pageBreakBefore?: boolean; contextualSpacing?: boolean; widowControl?: boolean; bidi?: boolean; [k: string]: unknown };
type WxTblP = { b?: WxBset; m?: Record<string, number>; ind?: number; jc?: string | null; shd?: string | null; [k: string]: unknown };
type WxCond = { r: WxRunP; p: WxParaP; t: WxTblP; c: { b: WxBset; shd: string | null | undefined } };
type WxSty = { type: string | null; def: boolean; based: string | null; r: WxRunP; p: WxParaP; t: WxTblP; tc: { shd: string | null | undefined }; cond: Record<string, WxCond> };
type WxLvl = { fmt: string; txt: string; start: number; p: WxParaP; r: WxRunP; suff: string; jc: string };
type WxRoot = { font: string; sz: number; b?: boolean; color?: string };
type WxCell = { tstyle: string | null | undefined; cond: { r: WxRunP; p: WxParaP } };
type WxCtx = { r: WxRunP; root: WxRoot; cell: WxCell | null | undefined; first: boolean | WxRunP };
type WxPara = { html: string; st: string; before: number; after: number; bdr?: WxBset; keep: boolean; pbb: boolean; pb: number; ctxSp: boolean; sid: string | null | undefined; tabs: (string | number)[][]; indL: number; label: boolean; empty: boolean; src?: number };
type WxCellR = { tc: Element; pr: Element | null; col: number; span: number; vm: string | null; rs?: number };
type WxRow = { cells: WxCellR[]; h: number; hr: string; head: boolean; cant: boolean; gb: number };
type WxTRow = { h: string; r: number; cant: boolean; head: boolean };
type WxTBlock = { h: string; tbl: boolean; first: boolean; last: boolean };
type WxTblOut = { nested?: string; blocks?: WxTBlock[] };
type WxItem = { k: string; x?: WxPara; h?: string; b?: WxTBlock };
type WxBlk = { h: string; pb?: boolean; tbl?: number; cont?: boolean; keep?: boolean };

/* ---- agent 06: Word pagination, print centre, entities, building blocks, Word-exact forms ---- */
/** Page geometry of a converted Word document, in points (bt / bb: the measured top / bottom of the body). */
type WxpPgSize = { w: number; h: number; mt: number; mb: number; ml: number; mr: number; hdr: number; ftr: number; bt?: number; bb?: number; [k: string]: unknown };
/** One page-flow block of a converted Word document (h: its HTML, images as @iN references). */
type WxpBlock = { id: string; h: string; pb?: unknown; keep?: unknown; tbl?: unknown; [k: string]: unknown };
/** A converted Word document without its images (what an exact document stores in d.ex). */
type WxpDocBase = { v?: number; page: WxpPgSize; defTab: number; font?: string; sz?: number; header?: string; footer?: string; blocks: WxpBlock[]; title?: string; cls?: string; hints?: boolean; [k: string]: unknown };
/** A converted Word document with its images (wxConvert's result, the input of the pagination). */
type WxpDoc = WxpDocBase & { imgs: Record<string, string> };
/** The options of the layout pass (wxLayout). */
type WxpLayout = { k?: number; defTab: number; page: WxpPgSize; noAnc?: boolean };
/** A leaf of a fragment in reading order: a text node or an atomic inline element (read through the interface its nodeType says). */
type WxpLeaf = Text & HTMLElement;
/** A split point inside a container. */
type WxpPt = { node: Node; off: number; el?: Node };
/** One table cell cut in two at a page end. */
type WxpCellCut = { ca: HTMLTableCellElement; cb: HTMLTableCellElement; c: number };
/** One fragment of a block on a page, and a page of fragments (k: the line-spacing factor of a tightened page). */
type WxpFrag = { id: string; part: number; html: string; tbl: boolean };
type WxpPage = WxpFrag[] & { k?: number };
/** The pagination cache of a Word-exact document (DC.wxPg). */
type WxpCache = { rev?: string; pages: WxpPage[] };
/** d.ex of a Word-exact document. */
type DcWxEx = WxpDocBase & { imgs?: Record<string, string>; off?: string | null; name?: string; official?: { authority: string; file: string; ver?: unknown; fills?: unknown } | null; rev?: string; pdf?: unknown };
type DcWxDoc = DcDoc & { ex: DcWxEx };
/** A fill-in place of a Word-exact document, listed in its panel. */
type DcWxField = { pi: number; i: number; lab: string; ok: boolean };
/** The print centre's state (DC.pr). */
type DcPrState = { dest: string; pages: string; range: string; gray: boolean; bg: boolean; cert: boolean; view: number; host: HTMLElement | null; n: number; cur: number; tok?: number; d?: DcDoc; nup?: number; hf?: DcxHf; [k: string]: unknown };
/** product phase 2: custom header / footer of the print centre (three slots each, with tokens) */
type DcxHf = { on: boolean; hl: string; hc: string; hr: string; fl: string; fc: string; fr: string; skip1: boolean };
/** A person or organisation a document is about (d.ents, the shared directory, API results). */
type DcEntity = { id?: string; type: string; ex?: boolean; api?: boolean; data: Record<string, string>; [k: string]: unknown };
/** The practitioner's details (d.pract). */
type DcPract = { spec?: string; rpps?: string; addr?: string; city?: string; tel?: string; mail?: string; fee?: string; [k: string]: unknown };
/** The optional entity API source (dcS.api). */
type DcEntApi = { url: string; token: string };
/** A rendered QR code image for the flow exports (DC._fimgs). */
type DcQrImg = DcFlowImg;
/** An override that forwards its `this` to the function it wraps (`_x.apply(this,arguments)`). */
type DcThisFn<F extends (...a: never[]) => unknown> = (this: unknown, ...a: Parameters<F>) => ReturnType<F>;

/** Agent 07-g (import review, "open as is", ODT and spreadsheet engines). */
/** A neutral import item (dcReadHtml / dcReadDocBin / slides): one record shared by every kind, as in the source. */
type DcLvItem = { k?: string; lv?: number; text?: string; html?: string; hs?: string; src?: string; pct?: number; rows?: string[][]; cs?: Bag; head?: boolean; var?: string; label?: string; ftype?: string; [k: string]: unknown };
/** A slide paragraph read from the PowerPoint XML (bullet groups). */
type DcLvPptP = { tx: string; lvl: number; num: boolean; none: boolean; bu: boolean; h?: string };
/** A font kept with a document: base64 (PDF import) or {d, w, s} (bytes or base64, weight, style). */
type DcLvFont = string | { d: string | Uint8Array; w?: number; s?: string } | null;
/** The "open as is" report kept on the document (d.ex.live). */
type DcLvLive = { eng: string; src: string; fid: string; notes: string[]; size: number; at: number };
/** d.ex of a Word-engine document (exact Word, PDF pages, documents opened as is). */
type DcLvEx = { blocks: { id: string; h: string; pb?: boolean; keep?: boolean; tbl?: boolean }[]; imgs?: Record<string, string>; fonts?: Record<string, DcLvFont>; store?: string; live?: DcLvLive; css?: string; cls?: string; grid?: boolean; slides?: boolean; name?: string; off?: string | null; rev?: string; [k: string]: unknown };
type DcLvDoc = DcDoc & { ex: DcLvEx };
/** What an engine returns: the Word-engine model, a fidelity and notes. */
type DcLvW = { title?: string; imgs?: Record<string, string>; fonts?: Record<string, DcLvFont>; css?: string; cls?: string; grid?: boolean; slides?: boolean; header?: string; footer?: string; hints?: boolean; [k: string]: unknown };
type DcLvRes = { W: DcLvW; fid: string; notes: string[] };
/** The page geometry of the Word engine (pt). */
type DcLvPage = { w: number; h: number; mt: number; mr: number; mb: number; ml: number; hdr: number; ftr: number };
/** What IndexedDB keeps for a document opened as is. */
type DcLvStored = { imgs?: Record<string, string>; fonts?: Record<string, DcLvFont>; orig?: ArrayBuffer | null; name?: string; mime?: string; at?: number };
/** A PDF text run (dcPdfToWx). */
type DcLvPdfRun = { t: string; x: number; y: number; size: number; w: number; fn: string; fam: string; asc: number; desc: number; rot: number; vert: boolean; col?: string; b?: boolean; i?: boolean };
/** A spreadsheet grid (dcGridBlock / dcGridW). */
type DcLvGridCell = { c?: number; skip?: boolean; txt?: string; v?: number | string | null; f?: string | null; nf?: string | null; st?: string; cs?: number; rs?: number; html?: string | null; auto?: boolean };
type DcLvGridRow = { r?: number; h: number; cells: DcLvGridCell[] };
type DcLvGrid = { name: string; cols: number[]; rows: DcLvGridRow[] };
type DcLvLiveDoc = DcDoc & { ex: DcLvEx & { live: DcLvLive } };
type DcLvFontO = { d: string | Uint8Array<ArrayBuffer>; w?: number; s?: string };
/** pdf.js parts the shared DcPdfPage / DcPdfDoc types leave out. */
type DcLvPdfPage = DcPdfPage & { commonObjs: { get: (n: string) => unknown }; cleanup: () => void };
type DcLvPdfFont = { name?: string; bold?: boolean; italic?: boolean; data?: Uint8Array<ArrayBuffer> };
type DcLvMeta = { title?: string; name: string; orig?: ArrayBuffer | null; mime?: string; eng?: string; src?: string; fid?: string; notes?: string[]; size?: number };
/** dcFontHere keeps its measuring canvas on itself. */
type DcLvFontHereFn = { (name: string): boolean; c?: CanvasRenderingContext2D | null };
/** A paragraph / picture / table / page break read by dcRtfToHtml. */
type DcLvRtfRun = { tx?: string; s?: boolean | number; u?: boolean | number; i?: boolean | number; b?: boolean | number; sup?: boolean | number; sub?: boolean | number; st?: string };
type DcLvRtfPara = { k: string; runs?: DcLvRtfRun[]; al?: string; pict?: { type: string; hex: string; gw?: number }; rows?: DcLvRtfRun[][][][] };
/** Options of dcLvFlowFromHtml. */
type DcLvFlowO = { css?: string; fixSrc?: (s: string) => string | null | undefined; theme?: boolean; fill?: boolean; page?: DcLvPage; sz?: number; font?: string; header?: string; footer?: string; title?: string; hints?: boolean };
/** OpenDocument styles: one family:name entry, and the resolved (inherited) style. */
type DcLvOdtStyle = { fam: string | null; par: string | null; list: string | null; master: string | null; p: Dict; t: Dict; c: Dict; col: Dict; tb: Dict; r?: Dict };
type DcLvOdtRes = { p: Dict; t: Dict; c: Dict; col: Dict; tb: Dict; r?: Dict; list: string | null; master: string | null };
type DcLvOdtLv = { bullet: boolean; ch: string; fmt: string; suf: string; pre: string; ind: number | null };
/** Excel cell formats (cellXfs) and fonts. */
type DcLvXlFont = { b?: boolean; i?: boolean; u?: boolean; s?: boolean; sz: number; c?: string | null; n: string };
type DcLvXlXf = { nf?: number; f?: DcLvXlFont; fl?: string | null; b?: Dict; h?: string | null; v?: string | null; w?: boolean | null; ind?: number | null; rot?: number | null };
type DcLvXlCell = { v: string | number | null | undefined; html: string | null; f: string | null; xf: DcLvXlXf; t: string | null };
/** An override of a function that calls the previous version with this/arguments: `this` is typed here, so the
 * override keeps the arity of the original (no `this` parameter in its list). */
type DcLvThis<F extends (...a: never[]) => unknown> = (this: unknown, ...a: Parameters<F>) => ReturnType<F>;

/* ---- agent 08 (slice tail): .pptx slide engine, grid recalc, save back to Word ---- */
/** One relationship of an OOXML part (_rels/*.rels): target path (or external URL), type URI. */
type PxRel = { t: string; type: string; ext: boolean };
type PxRels = Record<string, PxRel>;
/** A loaded .pptx part: its XML, its relationships, its path. */
type PxPart = { x: Document | null; r: PxRels; p: string };
/** A slide master's theme: colour scheme, major/minor fonts, colour map. */
type PxTheme = { sch: Record<string, string | null>; maj: string; min: string; map: Record<string, string> };
/** A shape's geometry in points. */
type PxXf = { x: number; y: number; w: number; h: number; rot: number; fh: boolean; fv: boolean; g: Element };
type PxPh = { type: string; idx: string | null };
type PxCtx = { TH: PxTheme; R: PxRels; L: PxPart | null; M: PxPart };
/** fillCss result: a CSS colour / gradient, or a picture fill ({img: key}). */
type PxFill = string | { img: string } | null;
type PxImgFill = { img?: string };
/** Inherited paragraph ("p:…") and run ("r:…") properties: attribute values or child elements. */
type PxProps = Record<string, string | Element | null>;
type PxSlideBlk = { id: string; pb: boolean; keep: boolean; tbl: boolean; h: string };
/** A grid cell clone that remembers the cell it was copied from. */
type LvSrcTd = HTMLElement & { __src?: HTMLElement };
/** The "open as is" state of a Word document (d.ex) as read here. */
type LvEx = { off?: string; store: string; name?: string; blocks: { h: string }[]; [k: string]: unknown };
