function dcActiveEd(){const s=getSelection();if(!s!.rangeCount)return null;const n=s!.anchorNode;const el=(n?.nodeType===1?n as Element:n?.parentElement)?.closest?.<HTMLInputElement>("[data-ed]");return el&&dcRoot()?.contains(el)?el:null}
