function dcWhere(){const r=DC.sel&&dcFind(DC.sel);if(r)return {pi:r.pi,bi:r.bi+1};const d=dcDoc();const pi=Math.min(DC.cur!,d.pages.length-1);return {pi,bi:d.pages[pi].blocks.length}}
