  const mv=(ev: PointerEvent)=>{let dx=(ev.clientX-sx)/pw*100;if((side==="l")!==rtl)dx=-dx;const raw=Math.max(20,Math.min(100,startW+dx));cur=snaps.reduce((a,b)=>Math.abs(b-raw)<Math.abs(a-raw)?b:a);el!.style.setProperty("--w",cur as unknown as string);tip.textContent=cur===100?"1":cur===50?"1/2":cur===33?"1/3":cur===25?"1/4":cur===66?"2/3":"3/4"};
  const up=()=>{removeEventListener("pointermove",mv);removeEventListener("pointerup",up);tip.remove();if(cur!==startW){r!.b.w=cur===100?undefined:cur;dcDoc().upd=Date.now();dcSave();dcRefresh("right");dcThumbsSoon()}else DC.undo!.pop()};
