function dcPopClose(){const p=DC.pop as (HTMLDivElement & DcElX) | null | undefined;if(!p)return;DC.pop=null;if(p._off)document.removeEventListener("pointerdown",p._off,true);p.remove()}
const DC_PAL=["#1f2933","#52606d","#9aa5b1","#ffffff","#e5484d","#e0662b","#c08a00","#18a058","#0f8f7e","#2f7cf6","#5a64e0","#8b5cf6","#d6457a","#7a4b2a"];
