const vphCat=(code: string)=>VPH_CAT.find(c=>c.code===code)||null;
const VPH_NOTICE=()=>Object.assign(B.callout('Document de travail','Pour la transmission à l\u2019Assurance maladie, reportez ces informations sur les modèles officiels opposables publiés sur handicap.gouv.fr : fiche d\u2019évaluation des besoins, fiche de préconisation (août 2026), certificat d\u2019essai en conditions réelles (juin 2026).','alert','amber'),{vph:'notice'});
function vphBlocks(code: string,mode: string){const cat=vphCat(code)||vphCat('FRMV');mode=mode||(cat!.modes.includes('achat')?'achat':cat!.modes[0]);
  const ot=(l: string,t: string|undefined,r: boolean|undefined,x: Bag={})=>F(l,t,r,Object.assign({role:'ot'},x)),pr=(l: string,t: string|undefined,r?: boolean|undefined,x: Bag={})=>F(l,t,r,Object.assign({role:'prescriber'},x));
  return{
  notice:VPH_NOTICE(),
  case:{id:uid(),type:'vphcase',code:cat!.code,cls:cat!.classes?cat!.classes[0]:'',mode,nomen:'nouvelle',prescDate:'',lastPurchase:'',keepTogether:true},
  check:{id:uid(),type:'vphcheck',keepTogether:true},
  owned:Object.assign(B.fieldgroup([{title:'VPH déjà possédé',fields:[pr('L\u2019usager possède déjà un VPH','radio',true,{options:['Non','Oui'],layout:'horizontal'}),pr('Catégorie','dropdown',false,{options:VPH_CAT.map(c=>c.code)}),pr('Date d\u2019acquisition ou de location','date'),pr('Modèle','text')]}]),{vph:'owned',cond:'vph:eval'}),
  needs:Object.assign(B.fieldgroup([{title:'Évaluation des besoins, 4 critères (équipe prescriptrice)',fields:[pr('Facteurs personnels','longtext',true,{help:'Âge, capacités cognitives et physiques, habitudes de vie.'}),pr('Pathologie','longtext',true,{help:'Diagnostic, évolution attendue, douleurs, risques cutanés.'}),pr('Usages et activités','longtext',true,{help:'Intérieur ou extérieur, transferts, durée d\u2019utilisation, activités.'}),pr('Facteurs environnementaux','longtext',true,{help:'Logement, accès, transports, aidants.'})]}]),{vph:'needs',cond:'vph:eval'}),
  measures:Object.assign(B.fieldgroup([{title:'Mesures du patient (ergothérapeute ou kinésithérapeute)',fields:[ot('Poids','number',true,{unit:'kg',min:3,max:300,bind:'weight'}),ot('Taille','number',true,{unit:'cm',min:40,max:230,bind:'height'}),ot('Largeur de bassin, assis','number',true,{unit:'cm',min:15,max:80}),ot('Profondeur d\u2019assise (dos au creux poplité)','number',true,{unit:'cm',min:15,max:70}),ot('Hauteur creux poplité au talon','number',true,{unit:'cm',min:15,max:70}),ot('Hauteur épaules, assis','number',false,{unit:'cm',min:20,max:90})]}]),{vph:'measures',cond:'vph:eval'}),
  preco:Object.assign(B.fieldgroup([{title:'Préconisation (prescripteur)',fields:[pr('Type d\u2019assise et de dossier','longtext',true),pr('Commande et conduite','longtext',false,{help:'Pour les fauteuils électriques et scooters.'}),pr('Adjonctions et options, avec justification','longtext',false,{help:'Une par ligne. Les options hors nomenclature passent par un devis et une DAP.'})]}]),{vph:'preco',cond:'vph:preco'}),
  trials:Object.assign(B.fieldgroup(['Essai comparatif 1','Essai comparatif 2','Essai en conditions réelles'].map(t=>({title:t,fields:[ot('Date','date',true),ot('Modèle essayé','text',true),ot('Lieu','text',false),ot('Résultat','radio',true,{options:['Concluant','Non concluant']})]}))),{vph:'trials',cond:'vph:trial'}),
  team:Object.assign(B.fieldgroup([{title:'Ergothérapeute ou masseur-kinésithérapeute',fields:[ot('Nom','text',true),ot('N° RPPS','text',true),ot('Signature','signature',true),ot('Date','date',true)]}]),{vph:'team',cond:'vph:team'}),
  presc:Object.assign(B.fieldgroup([{title:'Prescription définitive (médecin, consultation post-évaluation)',fields:[pr('Nom du médecin','text',true),pr('N° RPPS','text',true),pr('Spécialité','dropdown',false,{options:['Médecine physique et de réadaptation (MPR)','Titulaire d\u2019un DU appareillage','Autre prescripteur habilité']}),pr('Signature','signature',true),pr('Date','date',true)]}]),{vph:'presc'}),
  engage:[Object.assign(B.paragraph('En cas d\u2019achat, je m\u2019engage à remettre mon fauteuil roulant à un centre certifié lorsque je n\u2019en aurai plus l\u2019usage ou lorsqu\u2019il ne correspondra plus à mon besoin médical.'),{vph:'engage-text',cond:'vph:purchase'}),Object.assign(B.fieldgroup([{title:'Engagement de l\u2019usager',fields:[F('Nom','text',true),F('Signature','signature',true),F('Date','date',true)]}]),{vph:'engage',cond:'vph:purchase'})]};}
function vphDossier(code: string,mode: string){const x=vphBlocks(code,mode);return[x.notice,x.case,x.check,Object.assign(B.heading('Évaluation'),{level:1,cond:'vph:eval'}),x.owned,x.needs,x.measures,Object.assign(B.heading('Préconisation et essais'),{level:1,cond:'vph:trial'}),x.preco,x.trials,Object.assign(B.heading('Signatures'),{level:1}),x.team,x.presc,...x.engage];}
function tplVPH(){const d=defaultDoc();d.title='Dossier VPH';d.pages=[{id:uid(),blocks:[B.brand(),B.title('Dossier de prescription VPH','Véhicule pour personne en situation de handicap'),B.paragraph('Patient : <span class="mf" data-mf="patient.name" contenteditable="false">Patient name</span>, né(e) le <span class="mf" data-mf="patient.dob" contenteditable="false">Date of birth</span>. Poids <span class="mf" data-mf="patient.weight" contenteditable="false">Weight</span>, taille <span class="mf" data-mf="patient.height" contenteditable="false">Height</span>. Caisse : <span class="mf" data-mf="patient.caisse" contenteditable="false">Insurance office</span>.'),...vphDossier('FRMV','achat')]}];return d;}
