  bl[1]=B.title('Consentement aux soins','Loi du 22 ao\u00fbt 2002 relative aux droits du patient');
  bl.splice(4,0,B.section('Repr\u00e9sentation','Si je ne suis plus en mesure d\u2019exercer mes droits :',['je peux d\u00e9signer un repr\u00e9sentant qui interviendra \u00e0 ma place','ce repr\u00e9sentant est inform\u00e9 et consent en mon nom'],'user','blue'));
