    if(['script','style','noscript','template','iframe','object','nav','header','footer','form'].includes(t)&&!(t==='header'||t==='footer'))continue;
    if(/^h[1-6]$/.test(t)){const x=strip(htmlInline(n)).trim();if(!x)continue;if(t==='h1'&&!blocks.some(b=>b.type==='title')){blocks.push(Object.assign(B.title(x,''),{showSub:false}));}else blocks.push(Object.assign(B.heading(x),{level:Math.min(3,Math.max(1,+t[1]-1))}));stats.h++;}
