const dataURLOf=(bytes: BlobPart,mime: string)=>new Promise<string>(r=>{const fr=new FileReader();fr.onload=()=>r(fr.result as string);fr.readAsDataURL(new Blob([bytes],{type:mime}));});
const mimeOf=(n: unknown)=>{const e=String(n).split('.').pop()!.toLowerCase();return e==='jpg'||e==='jpeg'?'image/jpeg':e==='gif'?'image/gif':e==='webp'?'image/webp':e==='svg'?'image/svg+xml':e==='bmp'?'image/bmp':'image/png';};
