  const t_=(k: string)=>t(k);
  slides.push(cur={cover:true,title:dcTx(d.title,L),sub:[dcTx(d.clinic,L),dcFmtDate(d.date,L),d.prat].filter(Boolean).join(" · "),paras:[]});cur=null as DcSlide|null;
