  const top=(o: Record<string, number>)=>Object.keys(o).sort((a,b)=>o[b]-o[a])[0];const basePx=parseFloat(top(tal.sz)||rc.fontSize)||16,baseColor=top(tal.col)||rc.color,baseFam=top(tal.fam)||rc.fontFamily;
