    if(/^(P|DIV|LI|H[1-6]|BLOCKQUOTE|TD|TH)$/.test(el.tagName)&&cs.textAlign!==pc.textAlign&&/center|right|justify/.test(cs.textAlign))st.push("text-align:"+cs.textAlign.replace("-webkit-",""));
