    if((el.tagName==="P"||el.tagName==="DIV")&&!el.querySelector<HTMLInputElement>("p,div,table,ul,ol,img")){const tx=(el.textContent||"").trim();if(tx&&tx.length<100&&!/[.;,]$/.test(tx)){const spans=[el,...el.querySelectorAll<HTMLInputElement>("*")].filter(x=>[...x.childNodes].some(n=>n.nodeType===3&&n.nodeValue!.trim()));const allB=spans.length&&spans.every(x=>(parseInt(getComputedStyle(x).fontWeight)||400)>=600);const mx=Math.max(...spans.map(x=>parseFloat(getComputedStyle(x).fontSize)||basePx))/basePx;if(allB&&mx>=1.15||mx>=1.45)el.dataset.hd=mx>=1.6?"1":mx>=1.3?"2":"3"}}
