          const bg=/background-color:\s*([^;]+)/.exec(sty)||(td.getAttribute("bgcolor")?[0,td.getAttribute("bgcolor")]:null),co=/(?:^|;)\s*color:\s*([^;]+)/.exec(sty),al=/text-align:\s*(center|right)/.exec(sty)||/^(center|right)$/i.exec(td.getAttribute("align")||"");if(!o.clean){if(bg)st.bg=bg[1];if(co)st.c=co[1];if(al)st.al=al[1].toLowerCase();if(td.tagName==="TH"||td.querySelector<HTMLInputElement>("b,strong")||/font-weight:\s*(bold|[6-9]00)/.test(sty))st.b=1;if(Object.keys(st).length)cs[r+":"+j]=st}
