      const bold=/bold|black|heavy|semibold|demi/i.test(nm+fam),ital=/italic|oblique/i.test(nm+fam);if(!cur||Math.abs(y-cur.y)>Math.max(2,h*.4)){cur={y,x,runs:[],h,maxX:x+it.width!};lines.push(cur)}
