/* what is signed: the content, not the signatures or the workflow state */
function dcSigContent(d: DcDoc){return JSON.stringify({title:d.title,prat:d.prat,date:d.date,clinic:d.clinic,tag:d.tag,lang:d.lang||"",pt:d.pt||null,pract:d.pract||null,set:d.set,pages:d.pages})}
