function dcSigLog(d: DcDoc,ev: string,o: Bag={}){const s=dcSigEnsure(d);s.audit.push(Object.assign({at:Date.now(),ev},o))}
function dcSigNew(role: string,d: DcDoc){const sg: DcSigner={id:"sg"+Math.random().toString(36).slice(2,9),role,name:"",st:"wait"};if(role==="prat")sg.name=d.prat||"";if(role==="patient")sg.name=dcField("pt.full",d)||"";return sg}
