onDoc("contextmenu",e=>{const R=dcRoot();if(!R||!R.contains(tgt(e)))return;const c=(s: string)=>tgt(e).closest<HTMLInputElement>(s);let b: HTMLInputElement|null;
  if(c(".dc-mdl,.dc-rp,.dc-drawer,.dc-find,.dc-rib")||(c("input,textarea,select")&&!c("[data-ed]")))return;
  const stop=()=>{e.preventDefault();e.stopImmediatePropagation()};
  if(DC.view!=="editor"){if((b=c("[data-open]"))){stop();dcRowMenu(dcAnchorAt(e.clientX,e.clientY),b.dataset.open)}return}
  const d=dcDoc();if(!d)return;const lk=dcSigLocked(d);
  if((b=c(".dc-th"))){stop();if(lk){dcLockedMenu(e.clientX,e.clientY,null);return}dcThumbMenu(e,b);return}
  if((b=c(".dc-lp [data-goto]"))){stop();const id=b.dataset.goto;if(lk){dcLockedMenu(e.clientX,e.clientY,id);return}osMenu(e.clientX,e.clientY,[{l:t("dc_cmGo"),ic:DCI.chev,run:()=>b!.click()},"-",...dcBlockItems(id)]);return}
  if(!c(".dc-cv"))return;
  if(lk){stop();dcLockedMenu(e.clientX,e.clientY,c(".dc-b")?.dataset.b);return}
  if(DC.vm==="read")return;
  if(c(".dc-tbl td,.dc-tbl th"))return; /* table cells keep their row/column menu */
  const ed=c("[data-ed]");if(ed){stop();dcTextMenu(e,ed);return}
  if((b=c(".dc-b"))){stop();dcSelect(b.dataset.b!);dcBlockMenu(e.clientX,e.clientY,b.dataset.b);return}
  if((b=c(".dc-page"))){stop();dcPageMenu(e,b);return}},true);
