/* ===== v54 · entities: the people and organisations a document is about, a shared directory, and an optional API source ===== */
const DC_ENT: Record<string, { ic: string; f: string[] }>={patient:{ic:"user",f:["nom","prenom","dob","sexe","nir","mut","adr","tel","email","poids","taille","dossier"]},
  prat:{ic:"userplus",f:["nom","spec","rpps","addr","city","tel","mail","fee"]},
  guardian:{ic:"users",f:["nom","prenom","lien","tel","email","adr"]},
  prescriber:{ic:"clinical",f:["nom","spec","rpps","adr","tel","email"]},
  pro:{ic:"user",f:["nom","role","rpps","tel","email"]},
  org:{ic:"docs",f:["nom","finess","adr","tel","email"]},
  insurer:{ic:"shield",f:["nom","numero","adr","tel"]},
  supplier:{ic:"layers",f:["nom","siret","ameli","adr","tel","email"]}};
const DC_ENTX=["guardian","prescriber","pro","org","insurer","supplier"];
/* merge fields for every entity type */
DC_ENTX.forEach(ty=>DC_ENT[ty].f.forEach(f=>DC_FIELDS.push(["e."+ty+"."+f,"dc_et_"+ty,"dc_ef_"+f])));
{const _f=dcField;dcField=function(k,d?,L?): string{if(typeof k==="string"&&k.startsWith("e.")){d=d||dcDoc();const [,ty,f]=k.split(".");const e=((d.ents as DcEntity[] | undefined)||[]).find(x=>x.type===ty);const v=e&&e.data?e.data[f]:"";return v?String(v):""}return _f(k,d,L)}}
const dcEntName=(e: { data?: Record<string, string> })=>{const x=e.data||{};return [x.prenom,x.nom].filter(Boolean).join(" ")||x.nom||""};
const dcFLabel=([k,l,l2]: string[])=>l2?t(l2):t(l);
/* field menu grouped by entity */
dcFieldMenu=function(btn){dcKeepRange();const d=dcDoc();const grp: Record<string, string[][]>={pt:[],doc:[]};DC_ENTX.forEach(ty=>grp[ty]=[]);
  DC_FIELDS.forEach(x=>{const k=x[0];const g=k.startsWith("pt.")?"pt":k.startsWith("doc.")?"doc":k.startsWith("e.")?k.split(".")[1]:"doc";(grp[g]=grp[g]||[]).push(x)});
  const it=(x: string[])=>({l:dcFLabel(x)+"  ·  "+(dcField(x[0],d)||"—"),ic:DCI.dyn,run:()=>dcInsertField(x[0])});
  const items=[{l:t("dc_et_patient"),ic:DCI.user,sub:grp.pt.map(it)},{l:t("dc_et_prat"),ic:DCI.userplus||DCI.user,sub:grp.doc.map(it)},"-",
    ...DC_ENTX.map(ty=>({l:t("dc_et_"+ty)+(((d.ents as DcEntity[] | undefined)||[]).some(e=>e.type===ty)?"":"  ·  "+t("dc_ent_none")),ic:DCI[DC_ENT[ty].ic]||DCI.user,sub:grp[ty].map(it)}))];
  if(btn)dcMenuAt(btn,items);else{const s=getSelection();const r=s!.rangeCount?s!.getRangeAt(0).getBoundingClientRect():{left:innerWidth/2,bottom:innerHeight/2};osMenu(r.left,r.bottom+6,items)}};
