    const cap=dataCw(v)*8,bits: number[]=[];const put=(val: number,n: number)=>{for(let i=n-1;i>=0;i--)bits.push((val>>>i)&1)};put(4,4);put(bytes.length,v<10?8:16);bytes.forEach(b=>put(b,8));put(0,Math.min(4,cap-bits.length));put(0,(8-bits.length%8)%8);
