    while(i<L.length){const m=listRe.exec(L[i]);if(!m||ind(L[i])<base)break;if(ind(L[i])>base){const sub=list();if(items.length)items[items.length-1].sub+=sub;continue}
      if(/\d/.test(m[2])!==ordered)break;if(ordered&&items.length&&i>0&&isBlank(L[i-1])&&+(/\d+/.exec(m[2])![0])!==start+items.length)break;let text=m[3];i++;
      while(i<L.length&&!isBlank(L[i])&&!listRe.test(L[i])&&ind(L[i])>base){text+=" "+L[i].trim();i++}
      if(i<L.length&&isBlank(L[i])&&i+1<L.length&&listRe.test(L[i+1])&&ind(L[i+1])>=base)i++;
      const task=/^\[( |x|X)\]\s+(.*)$/.exec(text);items.push({h:task?`${task[1]===" "?"☐":"☑"} ${inl(task[2])}`:inl(text),sub:""})}
