  const {out}=dcRtfToHtml(src);const g=(k: string,d: number)=>{const m=new RegExp("\\\\"+k+"(-?\\d+)").exec(src);return m?+m[1]/20:d};const page={w:g("paperw",595.3),h:g("paperh",841.9),ml:g("margl",72),mr:g("margr",72),mt:g("margt",72),mb:g("margb",72),hdr:36,ftr:36};
