    if(x.k==="img"){const p=x.pict;if(p&&p.type!=="skip"&&p.hex.length>16){const bytes=new Uint8Array(p.hex.length/2|0);for(let k=0;k<bytes.length;k++)bytes[k]=parseInt(p.hex.substr(k*2,2),16);h+=`<p><img src="data:image/${p.type};base64,${dcB64U(bytes)}"${p.gw?` style="width:${(p.gw/20).toFixed(1)}pt"`:""}></p>`}continue}
