          const s0: (string)[]=[];const fn=cs["font-name"]||cs["font-family"];if(fn)s0.push("font-family:"+wxFont(fn));if(cs["font-size"])s0.push("font-size:"+cs["font-size"]);if(cs["font-weight"]==="bold")s0.push("font-weight:700");if(cs["font-style"]==="italic")s0.push("font-style:italic");if(cs.color)s0.push("color:"+cs.color);
