  const pres=await X("ppt/presentation.xml");if(!pres)throw new Error("PPTX");const sz=Dd(pres,"sldSz")[0];const SW=+(at(sz,"cx")||12192000)/12700,SH=+(at(sz,"cy")||6858000)/12700;
