  const imgs: Record<string, string>={};let ni=0;const imgKey: Record<string, string>={};const img=async (path: string): Promise<string|null>=>{if(imgKey[path])return imgKey[path];const d=await z.read(path);const m=dcMime(path);if(!d||!m||/emf|wmf/i.test(path))return null;const k="i"+(++ni);imgs[k]=`data:${m};base64,${dcB64U(d)}`;imgKey[path]=k;return k};
