      if(!v("prenom")||!v("nom")){err.hidden=false;err.textContent=t("dcx_send_need");m.querySelector<HTMLInputElement>(v("prenom")?'[data-dxp="nom"]':'[data-dxp="prenom"]')?.focus();return}
